import { existsSync, writeFileSync } from "node:fs";
import { join, resolve, sep } from "node:path";
import { resolveWorkspace } from "../compile/discover.js";
export async function recordDoctorEvidence(cwd, textbookId, compile, verification) {
    if (!/^[a-z0-9][a-z0-9-]*$/.test(textbookId)) {
        throw new Error(`Cannot record evidence for invalid textbook id: ${textbookId}`);
    }
    const workspace = await resolveWorkspace(cwd);
    const root = resolve(workspace.textbooksDir, textbookId);
    if (root !== workspace.textbooksDir && !root.startsWith(workspace.textbooksDir + sep)) {
        throw new Error(`Textbook path escapes workspace: ${textbookId}`);
    }
    if (!existsSync(root))
        throw new Error(`Cannot record evidence because textbook does not exist: ${textbookId}`);
    const path = join(root, "compile-result.md");
    const ok = compile.ok && (verification?.ok ?? true);
    const sections = [
        "# Verification Result",
        "",
        "Generated by Tutor Kit. Do not rewrite this file by hand.",
        "",
        `Result: ${ok ? "Passed" : "Failed"}`,
        `Scope: textbook ${textbookId}`,
        `Recorded: ${new Date().toISOString()}`,
        "",
        "## Compile",
        "",
        "```text",
        compile.output,
        "```"
    ];
    if (verification) {
        sections.push("", "## Coding problem verification", "", "```text", verification.output, "```");
    }
    writeFileSync(path, `${sections.join("\n")}\n`);
    return path;
}
